# Armenian rows: (definition, friendly, exampleGloss, root1, root2)
ROWS = [
    ("Քաղցրացնել կամ մաքրել՝ մի բանից հանել կոշտությունը։", "Հանել խայթը կամ դառնությունը մի բանից — բառացի քաղցրացնել, կամ փոխաբերաբար մեղմել խիստ միտքը, որ ավելի հեշտ կուլ գնա։", "Խմբագիրը edulcorated խիստ գրախոսությունը նախքան տպագրության ուղարկելը։", "դուրս, ամբողջությամբ", "քաղցր"),
    ("Չափազանց կամ կեղծավոր կերպով կրոնասեր, բարեպաշտ։", "Նկարագրում է մեկին, ում բարեպաշտությունը կարծես ցուցադրություն լինի — ավելի շատ բեմ, քան իսկական հավատ։", "Նրա pietistic հառաչանքները քարոզի ժամանակ զայրացնում էին նստարանի մյուսներին։", "բարեպաշտություն, պարտաճանաչություն", "բնույթ ունեցող"),
    ("Քերականական կառուցվածքից ծնված երկիմաստություն — նախադասություն, որ երկու կերպ է կարդացվում։", "Քերականորեն ճիշտ նախադասություն, որ կարող ես կարդալ երկու լրիվ տարբեր իմաստով, ինչպես \"I saw the man with the telescope.\"", "\"Visiting relatives can be tiring\" դասական amphiboly է — հոգնեցնո՞ւմ են ազգականները, թե՞ նրանց այցելելը։", "երկուսն էլ, երկու կողմից", "նետել"),
    ("Սուր, խորաթափանց, ուղիղ կտրում է էությանը։", "Կտրում է ավելորդը — trenchant դիտողությունը կամ միտքը արագ հասնում է սրտին, առանց ավելորդ խոսքի։", "Նրա trenchant քննադատությունը ֆիլմի սյուժեի ծակերին թաքստոց չթողեց։", "կտրել", "անել, որակ ունեցող"),
    ("Նոր սկսվող՝ վաղ կամ սաղմնային փուլում։", "Դեռ բացման րոպեներին է — ծրագիր, զգացում կամ ընթացք, որ նոր է ձև առնում։", "Պայմանագրի inchoative փուլերը խոստումնալից էին, բայց շատ մանրամասներ դեռ բաց էին։", "սկսել, սկիզբ դնել", "հակված դեպի"),
    ("Պաշտոնական խոսք կամ գրություն, որ մեկին բարձր է գովում։", "Լիարժեք, հանդիսավոր գովերգ — պատկերացրու շողշողուն հիշատակում կամ ելույթ, որ տանիքներից է երգում նրա նվաճումները։", "Թոշակի անցնող պրոֆեսորին ուղեկցեցին ամենամոտ ուսանողների panegyric։", "ամբողջը", "ժողով, հավաքույթ"),
    ("Իրական գոյության կամ փաստացի լինելիության վերաբերյալ, հակառակ վերացական տեսության։", "Իրերի մասին այնպես, ինչպես դրանք իրոք կան, ոչ միայն որպես գաղափարներ կամ տեսություններ դրանց մասին։", "Փիլիսոփաները վիճում են՝ թվերն ունե՞ն որևէ ontic կարգավիճակ, թե գոյություն ունեն միայն մեր մտքում։", "լինելը, այն ինչ կա", "վերաբերող"),
    ("Պտուղ տալ, կամ արգասավոր դառնալ։", "Վերջապես պտուղ տալ — ջանք, գաղափար կամ ներդրում, որ fructify է սերմից դարձել օգտակար բան։", "Տարիների լուռ հետազոտությունը վերջապես fructified աշխատող պատվաստանի։", "պտուղ", "անել, պատճառել"),
    ("Կանխատեսել կամ ներկայացնել մի բան որպես արդեն կատարված, դեռ չլինած ժամանակ։", "Գրականորեն առաջ ընկնել — ապագա իրադարձությունը նկարագրել որպես արդեն ավարտված, որ կետն ավելի ուժեղ ընկնի։", "Գեներալի proleptical կենացը \"victory\" ասվեց ճակատամարտից մի ամբողջ շաբաթ առաջ։", "առաջ", "վերցնել, բռնել"),
    ("Աշխատող օդի ճնշումով. նաև՝ ոգու կամ շնչի վերաբերյալ։", "Սովորաբար նշանակում է «սեղմված օդով շարժվող» — թեև կարող է նշանակել նաև ոգի կամ շունչ։", "pneumatic արգելակները սուլեցին, երբ ավտոբուսը մոտեցավ եզրաքարին։", "քամի, շունչ, ոգի", "պատկանող"),
    ("Աստծուն կամ աստվածայինը նկարագրել դրական պնդումներով — apophatic հակառակը։", "Աստծո մասին խոսել նրանով, ինչ Աստված է — \"God is love\" — ոչ միայն նրանով, ինչ Աստված չէ։", "Cataphatic աստվածաբանությունը վստահ խոսում է Աստծո մասին որպես սիրող, արդար և ողորմած։", "ներքև, ըստ", "խոսել, ասել"),
    ("Հիմնված վստահության կամ հավատի վրա. նաև՝ որպես հաստատուն հենակետ։", "Մի բան, որին վստահում ես ու դարձնում խարիսխդ — fiducial նշանը այն կայուն կետն է, որով չափում ես մնացածը։", "Հողաչափերը fiducial նշան դրեցին ժայռի մեջ՝ տարածքը քարտեզագրելուց առաջ։", "վստահել", "վստահություն, հավատ"),
    ("Աստծո բարության պաշտպանություն՝ չարի գոյության պայմաններում։", "Հնադարյան փորձը պատասխանելու՝ \"If God is good, why does evil exist?\"", "Նրա թեզը theodicy էր ուսումնասիրում Հոբի գրքի միջով։", "աստված", "արդարություն"),
    ("Փոխադարձ բնակություն — աստվածաբանական տերմին Երրորդության անձանց մեկը մյուսի մեջ լինելու համար։", "Աստվածաբանական բառ եռամիասնության այնքան լիակատար միասնության համար, որ յուրաքանչյուր մասը պարունակում է մյուսներին ու պարունակվում նրանցով։", "circumincession վարդապետությունը փորձում է բացատրել, թե ինչպես են Հայրը, Որդին և Հոգին տարբեր, բայց անբաժան։", "շուրջը", "գնալ, քայլել"),
    ("Հետևանք ունենալ, որ օգուտ է տալիս կամ արտացոլվում է մեկի վրա։", "Երբ պատիվը (կամ մեղքը) հետ է ցատկում պատասխանատուի վրա — բարի գործերը, որ redound են քո համբավին, շրջանով վերադառնում են քեզ պարգևելու։", "Թիմի հաջողությունը redound կլինի լուռ, աշխատասեր մարզչի վաստակին։", "հետ, նորից", "ալիք"),
    ("Անխուսափելի, որից չես կարող դուրս պրծնել։", "Անպայման կպատահի ինչ էլ անես — ineluctable ելքից չես ծուռ ճանապարհով դուրս գա։", "Ծերությունը գալիս է բոլորին. պարզապես ineluctable է։", "ոչ", "դուրս պրծնել"),
    ("Շրջանցիկ, բազմախոս ձևակերպում ուղիղ ձևի փոխարեն։", "Խոսքով երկար ճանապարհով գնալ — ասել \"make a decision\"՝ \"decide\" ասելու փոխարեն։", "Նրա periphrastic նամակները մեկ տողով կասեին այն, ինչին երեք պարբերություն էր ծախսել։", "շուրջը", "հայտարարել, պատմել"),
    ("Մտավոր բթություն կամ դանդաղկոտություն։", "Այն մշուշոտ, ծանր վիճակը, երբ մտածելը նման է օշարակի մեջ քայլելուն։", "hebetude ալիքը հարվածեց դասարանին հենց ճաշից հետո։", "բութ, անսուր", "վիճակ կամ որակ"),
    ("Անբարենպաստ. վատ նախանշան։", "Վատ նշան — պայմաններ կամ ժամանակ, որ կարծես քո դեմ են աշխատում՝ դեռ չսկսած։", "Մոխրագույն երկինքն ու մեռած մարտկոցը ճանապարհորդությանը տվեցին unpropitious սկիզբ։", "ոչ", "բարենպաստ, ողորմած"),
    ("Սոուսում շոգեխաշված կամ եփված միս — ճիշտ ուղղագրությունը \"fricasseed.\"", "Հին, ջերմ խոհարարական բառ կտրտած մսի համար, որ դանդաղ եփվում է սեփական սոուսում, մինչև փափկի։", "Տատիկի fricasseed հավը ամեն կիրակնօրյա ընթրիքի գագաթնակետն էր։", "տապակել", "կոտրել (կտորների)"),
    ("Արհեստական կամ ստորադաս փոխարինիչ։", "Կեղծը, որ կանգնում է իսկականի տեղը — տեխնիկապես աշխատում է, բայց բոլորը հասկանում են, որ իսկականը չէ։", "Պատերազմի գնորդները հաշտվում էին ersatz սուրճի հետ, որ եփում էին խորոված ցիկորիայից։", "դուրս, փոխարինման նախածանց", "դնել, տեղավորել"),
    ("Վերացական գաղափարը վերաբերվել որպես կոնկրետ իր։", "Գաղափարը զգացնել որպես ամուր ու իրական — մշուշոտ բանը, ինչպես \"the economy\", դարձնել մի բան, որ կարող ես ցույց տալ։", "Ազգի \"spirit\" որպես ինքնուրույն էակ անվանելը reifies մի բան, որ իրականում միլիոնավոր առանձին ընտրություններ է։", "իր", "դարձնել"),
    ("Ճարտարությամբ փախչել կամ խուսափել։", "Մաքուր սահել — խուսափել բռնումից, հարցից կամ պատասխանից, հաճախ խելքով կամ մազապուրծ։", "Պատասխանը ժամերով eluded նրան, մինչև հանկարծ ցնցուղում կտտացավ։", "դուրս, հեռու", "խաղալ"),
    ("Արտահայտող կասկած, շփոթվածություն կամ չլուծված հակասություն։", "Իսկական մտավոր փակուղում — ոչ ծուլությունից, այլ որովհետև հարցն ինքը դիմադրում է կոկիկ պատասխանին։", "Սոկրատեսը հաճախ երկխոսություններն ավարտում էր aporetic նոտայով՝ ավելի շատ հարցեր, քան պատասխաններ։", "առանց", "անցում, ճանապարհ"),
    ("Փոխաբերություն, որ բանը կոչում է կապված բառով, օրինակ \"the crown\"՝ միապետի համար։", "Կապված բառով փոխարինել իսկականը — ասել \"the White House announced\", երբ նկատի ունես վարչակազմը։", "\"Wall Street had a rough day\" metonymy է — իրականում նշանակում է ֆոնդային շուկան։", "փոփոխություն, հետո", "անուն"),
    ("Արմատախիլ անել. պոկել բնական միջավայրից։", "Մի բան (կամ մեկին) արմատներով հանել այն տեղից կամ մշակույթից, որին պատկանում է։", "Պատերազմը deracinated մի ամբողջ սերունդ՝ ընտանիքները ցրելով սահմաններից այն կողմ։", "հեռու, դուրս", "արմատ"),
    ("Հաճելի հնչող։", "Պարզապես հաճելի լսել — euphonious բառը, անունը կամ նախադասությունը ականջով սահում է գրեթե երաժշտորեն։", "\"Murmuring brook\" euphonious փոքրիկ արտահայտություն է՝ փափուկ ու հեշտ ասելի։", "լավ, բարի", "ձայն, խոսք"),
    ("Ընդհանրապես ենթադրվող կամ համարվող։", "Լայնորեն հավատացված, թեկուզ դեռ չապացուցված — մի բանի «ենթադրյալ» տարբերակը։", "Նամակի putative հեղինակը հետո պարզվեց լրիվ անծանոթ։", "մտածել, համարել", "բնույթ ունեցող"),
    ("Նոր ստեղծված բառ կամ արտահայտություն։", "Ստեղծված նոր բառ — թարմ հորինված, դեռ (կամ հազիվ) բառարանում։", "\"Doomscrolling\" սկսվեց որպես neologism ու արագ դարձավ առօրյա ժարգոն։", "նոր", "բառ, խոսք"),
    ("Զայրացած կամ վատատրամ։", "Վատ, դյուրագրգիռ տրամադրություն — արագ կծկվող, ինչպես հին մարդիկ հավատում էին, թե փայծաղն է կառավարում բնավորությունը։", "Նա splenetic պատասխան կրակեց նամակը կարդալուց վայրկյաններ անց։", "փայծաղ (զայրույթի նստավայր)", "ազդված"),
    ("Հակված բարոյախոսելու շքեղ կամ կեղծավոր կերպով։", "Սիրում է փոքրիկ կյանքի դասեր տալ ինքնահավան ձևով, կարծես ամեն նախադասություն բախտի թխվածքի մեջ գրված լինի։", "Նրա sententious կենացը \"the true meaning of friendship\" բոլորին ստիպեց նայել ժամացույցներին։", "կարծիք, ասացվածք", "լի"),
    ("Չափից շատ խոսող, հատկապես մանրուքների մասին։", "Պարզապես չի դադարում զրուցել — երկար շաղակրատում է մանր բաների մասին, երբ մյուսներն արդեն խոսք չունեն։", "garrulous տաքսու վարորդը պատմեց իր ամբողջ կյանքը, դեռ օդանավակայանից չհեռացած։", "շաղակրատել, շատախոսել", "հակված"),
    ("Հիմարություն, տհասություն։", "Մաքուր հիմարություն — մեկնաբանություն կամ ծրագիր այնքան տհաս, որ հազիվ է արժանի լուրջ պատասխանի։", "Ծրագրի կոպիտ fatuity պարզ դարձավ հենց փորձեցին այն։", "հիմար, տհաս", "լինելու վիճակ"),
    ("Ելույթի եզրափակիչ մասը, հաճախ ամփոփող։", "Ելույթի մեծ ավարտը — այն հատվածը, որտեղ խոսողը հավաքում է ամենը և մեխում կետը։", "peroration ժամանակ հանդիսատեսի կեսն արդեն ոտքի էր։", "միջով, մինչև վերջ", "խոսել, աղերսել"),
    ("Նույն մտքի ավելորդ կրկնություն այլ բառերով։", "Նույն բանը երկու անգամ ասել՝ առանց նոր բան ավելացնելու, ինչպես \"free gift\" կամ \"end result.\"", "\"It is what it is\" սիրելի tautology է նրանց, ովքեր խուսափում են իսկական բացատրությունից։", "նույնը", "բառ, խոսք"),
    ("Շատ քիչ բառերով խոսել. կարճախոսություն։", "Շատ բան ասել շատ քիչով — կարճ, կտրուկ պատասխանի արվեստը, անվանված Լակոնիայի սպարտացիների անունով, որոնք հայտնի էին խոսքի խնայողությամբ։", "\"Molon labe\" — \"come and take them\" — պատմության ամենահայտնի laconism է։", "Լակոնիայի սպարտացի", "սովորույթ, կերպ"),
    ("Անհամ, չափից պարզեցված գաղափարներ. սկզբնապես՝ անհամ կերակուր կամ շիլա։", "Նոսր, ջրով նոսրացված մտածողություն — բովանդակություն այնքան պարզ ու անվտանգ, որ մտքի համար սննդարար արժեք չունի։", "Քաղաքական գործչի ելույթը հիմնականում pabulum էր. մշուշոտ խոստումներ, որոնց ոչինչ չէիր կարող ամրացնել։", "կերակրել", "միջոց կամ գործիք"),
    ("Քուն կամ նիրհ առաջացնող։", "Այնքան ձանձրալի — կամ բառացի հանգստացնող — որ քուն է բերում։ Մտածիր տաք կաթի, կամ երեքժամյա բյուջետային նիստի մասին։", "Դասախոսության soporific միապաղաղը սենյակի կեսին ստիպում էր կոպերը բաց պահել։", "խոր քուն", "անել, պատճառել"),
    ("Չափից շողոքորթ, յուղոտ վարմունքով։", "Այնքան սահուն հմայիչ, որ սայթաքուն է թվում — շողոքորթություն այնքան հաստ, որ կարծես ճարպն ես զգում։", "unctuous վաճառողը շարունակ գովում էր իմ \"excellent taste\" ամեն լրացուցիչ վաճառքից առաջ։", "օծել, յուղել", "լի"),
    ("Արագ մեղք գտնող, մանրուքների նկատմամբ չափից քննադատ։", "Ծամծմող մինչև հիվանդություն — այն տեսակը, որ ամեն ինչում խնդիր է գտնում, նույնիսկ երբ կարևոր չէ։", "Նրա captious նշումները զեկույցի վրա ամբողջովին կենտրոնացած էին ստորակետների տեղադրության վրա։", "բռնել, վերցնել", "թակարդ, սոփիզմ"),
    ("Ծույլ, մտավոր կամ ֆիզիկապես անգործ։", "Դանդաղ ու կիսաքուն, ինչպես ձմեռող արջ — հազիվ շարժվում, հազիվ մտածում։", "Գրասենյակը torpid դարձավ օգոստոսի ծանր շոգին։", "թմրել, ծուլանալ", "վիճակում"),
    ("Կառավարիչ կամ պաշտոնյա, որ վարում էր միջնադարյան տունը։", "Միջնադարյան տարբերակը անձնակազմի ղեկավարի — վստահելի պաշտոնյան, որ օրեցօր վարում էր տիրոջ տունն ու կալվածքը։", "Ամրոցի seneschal կառավարում էր ամենը՝ բերքի հաշիվներից մինչև հյուրերի ցուցակը։", "ծեր, ավագ", "ծառա"),
    ("Երկար խոսել կամ գրել մի թեմայի շուրջ։", "Իսկապես մտնել թեմայի մեջ — խոսել կամ գրել անընդհատ, ծածկել ամեն անկյուն։", "Հարցրու նրան հնաոճ մեքենաների մասին, ու նա մի ամբողջ ժամ expatiate կանի։", "դուրս", "տարածություն"),
    ("Անարժեք, չնչին. նաև անվավեր կամ անարդյունավետ։", "Գրեթե ոչինչ չարժե — պայմանագրի nugatory կետն իրականում ոչինչ չի անում։", "Դատարանը հին կանոնադրությունը nugatory ճանաչեց, քանի որ երբեք չէր կիրառվել։", "մանրուքներ, անհեթեթություն", "պատկանող"),
    ("Իմաստություն, սուր դատողություն։", "Սուր, գործնական իմաստություն — այն բարի դատողությունը, որ գալիս է փորձից, ոչ միայն գրքերից։", "Հին նավապետի sagacity անձնակազմին մեկ անգամ չէ, որ փրկեց փորձանքից։", "սուր հոտառությամբ, խորաթափանց", "որակ"),
    ("Համայնական ամբոխը, զանգվածները, արհամարհանքով։", "Սնոբ, արհամարհական բառ \"the rabble\" կամ հասարակ ժողովրդի համար։", "Կոմսը ծաղրանքով նայեց պալատի դարպասների մոտ հավաքված canaille։", "շուն", "հավաքական, ոհմակ"),
    ("Անպատկառ, նվաստացնող վերաբերմունք կամ խոսք։", "Դաժան, արհամարհական վերաբերմունք՝ նվաստացնելու համար — այն վիրավորանքը, որ նախատեսված է ցավեցնելու։", "Նա տարիներով կրեց քննադատների contumely, մինչև աշխատանքը վերջապես ճանաչվեց։", "հետ, ամբողջությամբ", "ուռչել (հպարտությունից)"),
    ("Կասկածով կամ անհավանությամբ. կողմնակի հայացք։", "Այն թեք հայացքը, որ տալիս ես մի բանի, որին դեռ չես վստահում — կասկածով լի նայվածք։", "Ուսուցիչը askance նայեց կասկածելիորեն կոկիկ տնային աշխատանքին։", "դեպի, առ", "թեք, շեղ"),
    ("Հիմար մարդ. տականք գլուխ։", "Հինավուրց, գրեթե սիրալիր վիրավորանք այն մեկի համար, ով խիտ է կամ բթամիտ — տականք գլուխ։", "\"You clodpate,\" նա ծիծաղեց, \"you've had the map upside down the whole time.\"", "հողի կտոր", "գլուխ"),
    ("Շարժման կամ գործի դնել. մղել։", "Այն կայծը լինել, որ մի բան շարժում է — մեքենա միացնելը կամ մարդուն վերջապես գործի դնելը։", "Պայմանագիրը կորցնելու վախը actuated ամբողջ թիմին հանգստյան օրերի արտաժամյա աշխատանքի։", "գործ, մղում", "մղել, անել"),
    ("Վստահված միջոցների յուրացում։", "Հանգիստ գողանալ այն գումարը, որին վստահել էին խնամել — յուրացում՝ հին վերարկուով։", "Գանձապահի peculation գրեթե տասը տարի աննկատ մնաց։", "անձնական սեփականություն", "անասուն, հարստություն"),
    ("Խումբ, որ համարվում է պատշաճ հասարակության եզրին։", "Փայլուն-բայց-մութ սոցիալական ընդհատակ — մարդիկ, որ ապրում են «պատշաճ» հասարակության կանոններից հենց դուրս։", "Վեպը հետևում է երգչուհուն 1920-ականների կաբարեների demi-monde։", "կես", "աշխարհ, հասարակություն"),
    ("Դեռ գոյություն ունեցող. չոչնչացած կամ չկործանված։", "Դեռ այսօր կա — օգտագործվում է հին բաների համար (ձեռագրեր, տեսակներ, շենքեր), որոնք գոյատևել են։", "Առաջին տպագրության միայն երեք extant օրինակ է հայտնի։", "դուրս", "կանգնել"),
    ("Խաբեություն. վստահության դավաճանություն։", "Խոր, միտումնավոր դավաճանություն — կոտրել այն վստահությունը, որ մեկն իրավունք ուներ սպասել, որ կպահես։", "Գեներալը երբեք չներեց հին ընկերոջ perfidy բանակցությունների սեղանի մոտ։", "միջով, դեմ", "հավատ, վստահություն"),
    ("Տարածաշրջանային բարբառ, հատկապես ոչ ստանդարտ։", "Մարդկանց տեղական, առանձնահատուկ խոսելաձևը որոշակի շրջանում — լի բառերով ու ռիթմերով, որ օտարը կարող է չբռնել։", "Նրա տատիկը դեռ խոսում էր կղզու patois ընտանեկան ընթրիքներին։", "կոպիտ խոսք, բարբառ", "թաթ — ծանրաձև խոսք"),
    ("Հատուկ իրավունք, որ պատկանում է անձի կամ խմբի։", "Արտոնություն, որ միայն քոնն է — իրավունք, որ գալիս է քո դերից, պաշտոնից կամ կարգավիճակից։", "Ընտանիքի արձակուրդի վայր ընտրելը պապի prerogative է, ու բոլորը գիտեն։", "առաջ", "հարցնել, քվեարկել"),
    ("Համարձակություն, խիզախություն. նաև կոշտություն կամ դիմացկունություն։", "Կոշտ, խիզախ դիմացկունություն — նյարդը առաջ գնալու և կոշտությունը շարունակելու, երբ արդեն գնացել ես։", "Իսկական hardihood էր պետք ձնաբքի մեջ լեռնանցքը հատել առանց քարտեզի։", "համարձակ, կոփված", "վիճակ, պայման"),
    ("Ծաղկել. նաև զարգանալ կամ աստիճանաբար երևալ։", "Բացվել լիարժեք արտահայտման — ինչպես ծաղիկը բացվում է, կամ գաղափարը վերջապես դառնում է ինքն իրեն։", "Նրա լուռ գեղանկարչական տաղանդը effloresced, երբ ունեցավ սեփական արվեստանոց։", "դուրս", "սկսել ծաղկել"),
    ("Կշռով լար՝ ուղղահայացությունը որոշելու համար. փոխաբերաբար՝ դատողության չափանիշ։", "Կշիռ լարի վրա, որ կախվում է կատարյալ ուղիղ ներքև, որ ստուգես՝ արդյոք մի բան իսկապես ուղղահայաց է — և, ավելի լայն, ցանկացած հաստատուն չափանիշ, որով չափում ես մնացածը։", "Նա պապի ազնվությունն օգտագործում էր որպես մի տեսակ plumb line ամեն որոշման համար։", "կապար", "լար, չափ"),
    ("Ուրախությամբ, սիրով (հնացած)։", "Հինավուրց ձև ասելու \"gladly\" կամ \"with pleasure.\"", "\"I would fain rest here a while,\" հառաչեց ճանապարհորդը։", "ուրախ, ցնծալի", "ուրախությամբ, սիրով"),
    ("Խիստ հանրային քննադատություն կամ անպատվություն։", "Հանրային ամոթ, որ կույտով է թափվում մեկի վրա տեսանելի կերպով — անպատվություն լայն անհավանությունից։", "Սկանդալը հանրային opprobrium բերեց ամբողջ ընկերության վրա։", "դեմ", "անպատվություն, նախատինք"),
    ("Սուր ծաղրական, կծու խելքի կամ քննադատության մեջ։", "Խելք՝ իսկական ատամներով — mordant մեկնաբանությունը մի փոքր ցավեցնում է հենց նրա համար, որ այնքան ճարտար է նշանառված։", "Նրա mordant կինոգրախոսությունները վախեցնում էին ռեժիսորներին ու սիրված էին ընթերցողների կողմից։", "կծել", "կծող, անող"),
    ("Պաշտոնական հռչակագիր, հաճախ քաղաքական կամ ռազմական։", "Մեծ, պաշտոնական հայտարարություն — սովորաբար նոր կառավարություն, ապստամբություն կամ խոշոր հրամանագիր հայտարարող։", "Գեներալի pronunciamento լուսաբացին հայտարարեց նոր կառավարությունը։", "առաջ", "հայտարարել"),
    ("Մակերեսային գիտելիք ունեցող, որ ձևանում է փորձագետ։", "Մեկը, որ սահել է թեմայի մակերեսով, ապա խոսում է այնպես, կարծես դասագիրքն ինքն է գրել։", "Ընթրիքի sciolist վստահ ուղղեց սեղանի իրական աստղաֆիզիկոսին։", "իմանալ", "փոքրացուցիչ — փոքր գիտող"),
    ("Ծերության մտավոր ունակությունների անկում։", "Շատ ծեր տարիքի մշուշոտ, մոռացկոտ շերտը, երբ մտքի սրությունը սկսում է մարել։", "Իր dotage նա ամեն այցին պատմում էր նույն երեք պատմությունները, ամեն անգամ կարծես նոր լինեին։", "թուլամտել, հիմարանալ", "վիճակ կամ արդյունք"),
    ("Քամուց պաշտպանված կողմը։", "Հանգիստ, ապաստանած կողմը մի բանի — բլուր, նավ, պատ — որտեղ քամին հազիվ է հասնում քեզ։", "Քայլողները վրանը խփեցին լեռնաշղթայի lee side՝ պոռթկումներից խուսափելու համար։", "ապաստան, պաշտպանություն", "կող, երես"),
    ("Շեղել կամ հետ մղել հարված, հարց կամ փաստարկ։", "Սահուն հարվածել մի բան — սրի հարված, անհարմար հարց կամ մեղադրանք — առանց ռիթմը կորցնելու։", "Նա parried լրագրողի խորամանկ հարցը հեշտ կատակով։", "հետ մղել", "պատրաստել, պաշտպանել"),
    ("Գարշահոտ, թունավոր։", "Հոտը այնպիսին է, որ գրեթե թունավոր է թվում — գարշահոտություն այնքան վատ, որ շնչելը վտանգավոր է թվում։", "mephitic հոտ բարձրացավ ճահճից, երբ արևը մայր մտավ։", "թունավոր գոլորշի", "բնույթ ունեցող"),
    ("Մարդ, որ նվիրված է շքեղությանն ու հաճույքին։", "Մեկը, որ ապրում է հարմարության ու վայելքի համար — նուրբ ուտելիք, փափուկ մահճակալներ, հեշտ կյանք — անվանված հին հունական Սիբարիս քաղաքի անունով, որ հայտնի էր չափազանցությամբ։", "Իսկական sybarite, նա մերժում էր ցանկացած հյուրանոցային սենյակ առանց լոգարանի։", "հին հունական քաղաք՝ հայտնի շքեղությամբ", "բնակիչ"),
    ("Դիտավորյալ մի կողմ դնել կամ անտեսել մի մասը։", "Մտովի մի կտոր հանել գլուխկոտրուկից՝ մնացածի վրա մաքուր կենտրոնանալու համար։", "Եկեք մի պահ prescind արժեքից ու պարզապես հարցնենք՝ արդյոք ծրագիրն իսկապես աշխատում է։", "առաջ, հեռու", "կտրել"),
    ("Խստորեն քննադատել. նաև մաշկը մերկացնել։", "Պատառոտել մեկին խիստ քննադատությամբ — բառերով, կարծես բառացի մաշկը հանես։", "Քննադատները excoriated շարունակությունը՝ բնօրինակի ամեն սիրելի բանը դավաճանելու համար։", "դուրս", "մաշկ, կաշի"),
    ("Մեջբերել որպես ապացույց կամ վկայություն։", "Առաջ բերել փաստ կամ օրինակ՝ քո կետը հենելու համար — այն բանը, որ ցույց ես տալիս, երբ հարցնում են \"what's your evidence?\"", "Փաստաբանը adduced երեք վկա՝ վստահորդի ալիբին հենելու համար։", "դեպի, առ", "տանել"),
    ("Ճամփորդություններ կամ թափառումներ, հատկապես երկար ու լայնածավալ։", "Երկար, թափառող ճանապարհորդություններ — այն լայնածավալ շրջելը, որ քեզ երկար ժամանակ տանում է տնից հեռու։", "Նրա peregrinations երեք մայրցամաքներով լցրին ճամփորդական օրագրերի մի ամբողջ դարակ։", "միջով", "դաշտ, երկիր (peregrinus՝ օտարական)"),
    ("Մուրացիկ, կամ ողորմությամբ ապրող։", "Մեկը, որ ապրում է բարեգործություն խնդրելով — պատմականորեն նաև նկարագրում էր վանականներին, որ աղքատության ուխտ էին անում ու ապրում նվիրատվություններով։", "mendicant վանականները ոչինչ չունեին ու ամբողջովին հենվում էին գյուղացիների բարության վրա։", "մուրալ", "մուրացիկ"),
    ("Չափազանց առատաձեռն։", "Առատաձեռն մեծ, գրեթե ցուցադրական մասշտաբով — այն նվերը, որ մարդկանց մի փոքր շունչ է կտրում։", "munificent նվիրատվությունը ֆինանսավորեց գրադարանի ամբողջ նոր թևը։", "նվեր, ծառայություն", "անել, տալ"),
    ("Սննդի պակասից հյուծվածություն. նաև կենսունակության պակաս։", "Թույլ, սպառված վիճակ չսնվելուց կամ չվառելիքավորվելուց — բառացի սովից, կամ փոխաբերաբար, երբ այլևս բան չի մնացել վազելու։", "Պաշարման վերջում զինվորները մոտ էին inanition։", "դատարկ, ունայն", "արարք կամ արդյունք"),
    ("Դառը, վիրավորական քննադատություն։", "Քննադատություն, որ արդարից շատ անցել է ու դարձել զայրացած, դառը ճառ։", "Առցանց մեկնաբանությունները րոպեների ընթացքում լուծվեցին մաքուր vituperation։", "արատ, մեղք", "պատրաստել, մատակարարել"),
    ("Թշնամական, վնասակար ազդեցությամբ։", "Քո դեմ աշխատող, թեկուզ լուռ — պայմաններ կամ վերաբերմունք, որ անբարեհաճ են քո շահերին։", "Նոր քաղաքականությունը inimical էր փոքր բիզնեսներին, նույնիսկ եթե դա մտադրությունը չէր։", "ոչ", "ընկեր"),
    ("Հակված նախանձ կամ դժգոհություն առաջացնելու, հաճախ անարդար համեմատություններով։", "Անպայման մեկին վիրավորված կզգացնի — սովորաբար որովհետև մարդկանց կամ բաները անարդար է դասավորում իրար դեմ։", "Եղբայրներին դասավորել ըստ \"who Mom loves best\" invidious խաղ է, որ ոչ ոք չպետք է խաղա։", "նախանձ", "նայել (վատ կամքով)"),
    ("Ավելի ցածր աստիճանի կամ կարգավիճակի մարդ. ստորադաս։", "Մեկը հրամանատարության կամ սոցիալական սանդուղքի ավելի ցածրում — կրտսեր, որ աշխատում է ավելի հզորի տակ։", "Որպես երիտասարդ subaltern, նա երկար հրամաններ էր ստանում, մինչև ինքը տա։", "տակ", "փոխարինող, այլ"),
    ("Զգալ կամ արտահայտել ուժեղ ատելություն։", "Այնքան զզվել մի բանից, որ բարձրաձայն անիծես — մաքուր, ձայնավոր զզվանք։", "Գյուղացիները execrated հարկահավաքին ամեն անգամ, երբ նրա սայլը գլորվում էր քաղաքով։", "դուրս", "սուրբ (անիծել սրբից դուրս)"),
    ("Բնական արտաքին ծածկույթ, ինչպես մաշկ կամ խեցի։", "Բնության սեփական պաշտպանիչ փաթեթավորումը — մաշկ, խեցի, կեղև կամ կեղևապատ, ինչ որ ծածկում ու պաշտպանում է կենդանի բանը։", "Կրիայի խեցին զարմանալիորեն ամուր integument է։", "վրա, վրայից", "ծածկել"),
    ("Անմեղ, միամիտ, մանկական պարզություն ցույց տվող. \"disingenuous.\" հակառակը։", "Բաց վստահող ու մի փոքր միամիտ, առանց թաքնված օրակարգի — հեշտ է շփոթել \"ingenious\" հետ, որ նշանակում է խելացի։", "Նրա ingenuous հարցը — \"why would anyone lie about that?\" — ցույց տվեց, թե որքան քիչ խորամանկություն ուներ։", "մեջ, բնիկ", "ծնել (ազատածին, անկեղծ)"),
    ("Չափից մտահոգվածություն մանր մանրամասներով կամ կանոններով։", "Կորել մանր կանոններում ու բաց թողնել մեծ պատկերը — տարվել այն մանրատառով, որ ոչ ոքի չի հետաքրքրում։", "Նրա pedantry Օքսֆորդի ստորակետների մասին գցեց ամբողջ նիստը։", "երեխաների դաստիարակ", "սովորույթ կամ որակ"),
    ("Մանրակրկիտ, զգույշ քննություն։", "Խոր, ոչ մի քար չթողնող հայացք մի բանի — ամեն մանրուքը իսկական խնամքով անցնել։", "Միայն հաշվապահական գրքերի զգույշ perscrutation հետո երևաց անհամապատասխանությունը։", "միջով, ամբողջությամբ", "որոնել, քննել"),
    ("Առարկություն բարձրացնել. դժկամություն ցույց տալ։", "Քաղաքավարորեն հետ մղել կամ տատանվել՝ անմիջապես համաձայնելու փոխարեն — փափուկ \"I'd rather not.\"", "Երբ խնդրեցին ստորագրել առանց կարդալու, նա demurred։", "ից, հեռու", "հետաձգել"),
    ("Մակերեսորեն հավանական, բայց իրականում սխալ։", "Առաջին հայացքից համոզիչ է հնչում, բայց փլվում է հենց որ իսկապես ստուգում ես։", "\"Everyone's doing it\" specious փաստարկ է, որ երբեք չի դիմանում քննությանը։", "տեսք, արտաքին", "լի (գեղեցիկ թվացող)"),
    ("Անկեղծ չհնչող, կեղծավոր խոսք, հաճախ բարոյախոսական։", "Քարոզչական խոսք, որ առաքինի է հնչում, բայց իրական զգացում չունի — բարոյական կեցվածք ավտոմատի վրա։", "Նա հոգնել էր ընկերության cant \"family\" մասին մի ընկերությունից, որ ոչ մեկին արձակուրդ չէր տալիս։", "երգել (հետո՝ երգեցիկ ժարգոն)", "մուրացիկների նվնվոց, ապա կեղծավորություն"),
    ("Առանց խիզախության, վախկոտ։", "Երկչոտ մինչև անողնաշարություն — չափից վախեցած կանգնելու նույնիսկ երբ պարզ է, որ կարևոր է։", "Խորհրդի pusillanimous լռությունը թողեց, որ սկանդալը դուրս գա վերահսկողությունից։", "շատ փոքր", "ոգի, խիզախություն"),
    ("Աղվեսանման. խորամանկ, ճարպիկ։", "Խորամանկ ու խելացի աղվեսի պես — սրամիտ, մի փոքր գաղտնի, միշտ մեկ քայլ առաջ։", "Նա vulpine ժպիտ տվեց հենց որ նկատեց ծակը։", "աղվես", "ի, նման"),
    ("Մեկը մյուսի հետևից, հաջորդականությամբ։", "Խստորեն մեկ առ մեկ, հերթով — առանց առաջ թռչելու, առանց երկուսը միանգամից անելու։", "Դատավորը հասցեագրեց տասներկու պահանջներից յուրաքանչյուրը seriatim։", "շարք, հաջորդականություն", "մեկ առ մեկ"),
    ("Ծայրահեղ խնայողություն. ժլատություն։", "Փողը (կամ խոսքը, կամ ռեսուրսները) սեղմել ողջամիտ խնայողությունից շատ անց։", "Նրա parsimony լեգենդար էր — թեյի տոպրակները երեք անգամ էր օգտագործում։", "խնայել, տնտեսել", "վիճակ կամ սովորույթ"),
    ("Ուղղում, հատկապես տեքստում։", "Ուղղում գրության մեջ — գիտնականի նրբում, որ սխալ է ուղղում հին կամ կարևոր տեքստում։", "Նոր հրատարակությունը ներառում է տասնյակ emendations բնօրինակ ձեռագրին։", "դուրս", "մեղք, սխալ"),
    ("Չափավոր ուտելու և խմելու մեջ։", "Դիտավորյալ զսպված ուտելիքի ու խմիչքի շուրջ — երբեք չափից շատ, միշտ մի քիչ թողնել ափսեի վրա։", "Նրա abstemious սովորությունները նրան սուր էին պահում երկար այն բանից հետո, երբ հասակակիցներն արդեն դանդաղել էին։", "հեռու", "հարբեցնող խմիչք"),
    ("Քերականական սխալ կամ վարվելակարգի խախտում։", "Սայթաքում քերականության կամ վարքի մեջ — այն փոքր սխալը, որ խստապահանջին կծկեցնում է։", "\"Between you and I\" տարածված solecism է, որ դեռ ստիպում է քերականներին կծկվել։", "Կիլիկիայի քաղաք՝ հայտնի «վատ» հունարենով", "սովորույթ, կերպ"),
    ("Խմբի ներսում հակամարտության վերաբերյալ. փոխադարձ կործանարար։", "Ներքին կռիվ, որ խմբին ներսից է պատառոտում — կռիվ, որտեղ բոլորը պարտվում են, որովհետև ընտանիքն է ընտանիքի դեմ։", "Կուսակցության internecine վեճերն ավելի շատ վնաս տվեցին, քան որևէ արտաքին հակառակորդ կարող էր։", "միջև, մեջ", "սպանել"),
    ("Անտարբեր, անհոգ վերաբերմունք։", "Ուսերի թոթվելը դարձած ամբողջ անհատականություն — այնքան քիչ հոգալ այն բաների մասին, որ ժամանակին կարևոր էին, որ այլևս ոչինչ արժանի չի թվում ջանքին։", "Նրա pococurante վերաբերմունքը մրցանակաբաշխության նկատմամբ զարմացրեց բոլորին, ովքեր գիտեին, թե որքան էր աշխատել։", "քիչ", "հոգալ"),
    ("Շփոթված, բարդ իրավիճակ կամ վեճ։", "Խճճված, խառը իրավիճակ, որ դժվար է հասկանալ — մասամբ թյուրիմացություն, մասամբ դրամա, ամբողջովին շփոթմունք։", "Ամբողջ նստատեղերի աղյուսակի imbroglio սկսվեց մեկ սխալ դրված անվան քարտից։", "մեջ", "խճճել, շփոթել"),
    ("Սպառնացող, վախեցնող։", "Անսխալ սպառնալիքի օդ կրող — minatory հայացքը կամ նամակը շատ պարզ է դարձնում, որ վատ բան կարող է հետևել։", "Նամակի minatory տոնը վարձակալին անհանգստացրեց դեռ ծրարը չբացած։", "սպառնալ", "ծառայող"),
    ("Ուժեղ հանրային քննադատություն կամ բանավոր վիրավորանք։", "Բարձր, հանրային դատապարտում — այն այրող քննադատությունը, որ խաղում է բոլորի աչքի առաջ։", "Ազդարարը տարիներով կրեց հանրային obloquy, մինչև պատմությունը ապացուցեց, որ նա ճիշտ էր։", "դեմ", "խոսել"),
    ("Հանկարծակի բուռն պոռթկում՝ զգացմունքի կամ գործողության։", "Հանկարծակի, ուժեղ պոռթկում, որ միանգամից է կլանում քեզ — ծիծաղի, զայրույթի կամ հազի նոպա, որ ալիքի պես է հարվածում։", "Նրան բռնեց ծիծաղի paroxysm, որ չէր կարող բացատրել սենյակի մյուսներին։", "անդին", "սուր, սուրածայր"),
    ("Ավելացված արտաքին աղբյուրից, ոչ բնածին։", "Դրսից պտուտակված, ոչ սկզբից կառուցված — հավելում, ոչ միջուկ։", "Մեկնաբանությունը adscititious է թվում, կարծես կպցված լինի արդեն ավարտված տեքստին։", "դեպի, ի հավելումն", "հաստատել, վերցնել"),
    ("Գիտելիքի պակաս, անտեղյակություն։", "Պարզ չիմանալը — գիտելիքի բացը, առանց որևէ դատողության կցված։", "Նա խոստովանեց իր nescience ֆրանսիական գինու մասին ու թողեց, որ սոմելյեն ընտրի։", "ոչ", "իմանալ"),
    ("Չափից հետաքրքրություն սեռական հարցերում։", "Չափից եռանդուն, շեղ հայացքով հետաքրքրություն ամեն կծու բանի նկատմամբ — հետաքրքրություն, որ առողջից անցել է հետաքրքրասեր միջամտության։", "Թերթի prurience զույգի անձնական կյանքի նկատմամբ սահմանակից էր մոլուցքին։", "քոր գալ, կարոտել", "վիճակ"),
    ("Մուրով պատված, մութ, պղտոր։", "Մութ ու ծխոտ տեսքով, կարծես ամեն ինչ պատված լինի մուրի բարակ շերտով։", "fuliginous մշուշը կախված էր գործարանային քաղաքի վրա մթնշաղին։", "մուր", "լի"),
    ("Հերքել կամ հակասել։", "Ուղիղ խոսել մեկի ասածի դեմ — ասել \"that's not so.\"", "Ոչ ոք չէր համարձակվում gainsay հին նավապետի պատմությունը փոթորկի մասին։", "դեմ", "խոսել"),
    ("Ծուլություն, դանդաղկոտություն (լատիներենից)։", "Հին լատիներեն բառ մաքուր ծուլության համար — այն քարշը, երբ ոչինչ չես ուզում անել։", "Վանականները քարոզում էին ընդդեմ ignavia որպես հոգու լուռ վտանգներից մեկը։", "ոչ", "զբաղված, աշխատասեր"),
    ("Վահան՝ զինանշան ցուցադրող։", "Վահանաձև խորհրդանիշը, որ ցույց է տալիս ընտանիքի զինանշանը — նրա հերալդիկ «անվանակոճակը»։", "Ընտանիքի escutcheon դեռ կախված է հին կալվածքի առջևի դռան վերևում։", "վահան", "փոքրացուցիչ / առարկա"),
    ("Հնացած, դուրս եկած, կամ տարիքից թոշակառու։", "Անցել է օգտակար գագաթնակետը ու դուրս է թողնված արոտ — չափից հնաոճ կամ մաշված՝ աշխատանքը շարունակելու համար։", "superannuated տպիչը վերջապես փոխարինվեց տասնհինգ տարի խցանվելուց հետո։", "անդին", "տարի"),
    ("Փոխարինիչներ, հատկապես բժշկության մեջ։", "Փոխարինող դեղամիջոցներ, երբ իսկական բուժումը չկա — ըստ էության բժշկական փոխարինողներ։", "Պատերազմի բժիշկները հաճախ հենվում էին succedanea վրա, երբ պատշաճ դեղերը սպառվում էին։", "ի փոխարեն", "գնալ, զիջել"),
    ("Գովեստախոս, պարծենկոտ խոսք։", "Մեծ, աղմկոտ պարծենկոտություն — բարձր խոսք սեփական մեծության մասին, որ հիմնականում տաք օդ է։", "Նրա rodomontade նախագիծը \"single-handedly\" փրկելու մասին ոչ մեկին չխաբեց, ով իրոք այնտեղ էր եղել։", "պարծենկոտ ասպետ՝ Orlando Furioso", "գործողություն, ցուցադրություն"),
    ("Խորամանկությամբ կամ խաբեությամբ հասնել մի բանի։", "Նպատակին հասնել գաղտնի հնարքներով, ոչ ազնիվ խաղով։", "Նա chicaned գործարքը մանրատառով լի պայմանագրով։", "ծամծմել, խաբել", "խորամանկություն. հետո սուր շրջադարձ"),
    ("Ուսման կամ գիտելիքի մաքուր, վերացական գիտությունը, հաճախ մաթեմատիկա։", "Ուսումը իր ամենամաքուր, ամենավերացական ձևով — գիտելիքի խորը կառուցվածքը ինքնին, հատկապես մաթեմատիկական տեսակը։", "Փիլիսոփան երազում էր համընդհանուր mathesis, որ կարող էր միավորել գիտելիքի ամեն բնագավառ։", "սովորել", "սովորելու արարքը"),
    ("Չափից մտահոգված պաշտոնական կանոններով կամ մանր մանրուքով։", "Չափից խիստ մանրուքների նկատմամբ — ուղղել տեխնիկական մանրամասներ, որ իրականում ոչինչ չեն փոխում։", "Մի քիչ pedantic էր թվում վիճել \"who\" ու \"whom\" տեքստային հաղորդագրության մեջ։", "երեխայի ուղեկցող, դաստիարակ", "կերպ ունեցող"),
    ("Փայլատակող, շողշողուն լույս։", "Արագ, շողշողուն լույսի բռնկում — մտածիր ջրի վրա ցատկող արևի, կամ ադամանդի լույս բռնելու մասին։", "Ջահի coruscation լույս էր ցրում պարասրահի ամեն անկյունում։", "շողալ, փայլատակել", "արարքը"),
    ("Սկսնակ, նորեկ։", "Մեկը, որ լրիվ նոր է հմտության կամ բնագավառի մեջ — դեռ սովորում է պարանները, դեռ փորձագետ չէ։", "Նույնիսկ tyro շախմատիստը կարող է նկատել այդ սխալը։", "նորակոչիկ, նորեկ", "հում երիտասարդ զինվոր"),
    ("Չափազանց վատ, զզվելի։", "Վատ այնպես, որ արժանի է իսկական զզվանքի — ոչ միայն \"mediocre\", այլ իսկապես զզվելի։", "Գրախոսը շարունակությունը կոչեց execrable, ու տոմսարկղի թվերն համաձայն էին։", "անիծել", "արժանի, կարող"),
    ("Արյան կարմիր գույնի։", "Խոր, վառ կարմիր — թարմ արյան գույնը, հայտնի Շեքսպիրի Մակբեթից։", "Մայրամուտը ամբողջ երկինքը դարձրեց incarnadine փայլ։", "մեջ", "միս (մսակարմիր)"),
    ("Փոքր բաց կամ տարածություն իրերի միջև։", "Այն փոքրիկ միջանկյալ տարածությունը, որ հեշտ է բաց թողնել — տախտակների միջի ճեղքը, ժամանակացույցի բացը։", "Մոլախոտերը դուրս էին գալիս հին աղյուսե արահետի ամեն interstice։", "միջև", "կանգնել"),
    ("Քննադատական կամ դատապարտող դիտողություններ։", "Սուր, անհավանող մեկնաբանություններ — այն քննադատությունը, որ մի փոքր նկատողության տոն ունի։", "Պրոֆեսորի animadversions շարադրության վրա լցրին լուսանցքները կարմիր թանաքով։", "միտք", "շրջվել դեպի"),
    ("Անհերքելի, անժխտելի։", "Այնքան ամուր ապացուցված, որ վիճել չես կարող — գործը պարզապես փակ է։", "ԴՆԹ ապացույցը irrefragable էր, ու դատավարությունն ավարտվեց մեկ ժամում։", "ոչ", "հակադրվել, դիմադրել"),
    ("Բարդություն, խճճվածություն. նաև ներս փաթաթվել։", "Խճճված, ինքն իր վրա ծալված բարդություն — բաներ այնքան ամուր փաթաթված իրար, որ դժվար է բաժանել։", "Սյուժեի involution հանդիսատեսի կեսին ստիպեց վարկանիշներից հետո քանդել այն։", "մեջ, ներս", "գլորել, շրջել"),
    ("Ուժ կամ ջանք, ինչպես \"by dint of.\" արտահայտության մեջ։", "Մաքուր ջանք կամ ուժ — այսօր հիմնականում ապրում է \"by dint of.\" արտահայտության մեջ։", "Նա քննությունն անցավ by dint of մաքուր, համառ պարապմունքի։", "հարված, խփոց", "ուժով"),
    ("Միացված փոս-և-փայտ հոդով. ամուր տեղավորված իրար։", "Կողպված հին հյուսնի ձևով — մի կտորը սերտ տեղավորվում է հենց իր համար կտրված փոսի մեջ։", "Հին գոմի գերանները mortised էին իրար առանց մեկ մեխի։", "բույն, փոս", "կծվածք, բռնում"),
    ("Խիստ տեղին, համապատասխան։", "Հենց ճիշտ համընկնում պահին — մեկնաբանություն, մեջբերում կամ օրինակ, որ կատարյալ է ընկնում կետի վրա։", "Նրա apposite դիտողությունը ամբողջ բանավեճը մեկ նախադասությամբ ամփոփեց։", "դեպի", "դնել"),
    ("Փափուկ շողացող կամ թրթռացող (լույս). նաև՝ թեթև խելք։", "Նրբորեն շողացող, ոչ բոցավառ — փափուկ, թրթռացող լույս, կամ խելք, որ խաղային է, ոչ սուր։", "Մոմի լույսը lambent փայլ գցեց հին ճաշասենյակի վրա։", "լիզել", "անող (լույս, որ «լիզում է»)"),
    ("Կրոնական ճգնավոր, որ ապրում է միայնության մեջ։", "Մեկը, որ ամբողջովին հեռանում է աշխարհից՝ միայնակ ապրելու աղոթքի ու խորհրդածության մեջ։", "anchorite երեսուն տարուց ավելի ապրեց եկեղեցուն կցված փոքր խցում։", "հետ, հեռու", "հեռանալ"),
    ("Հագեցնել ծարավը. մարել։", "Լիովին հագեցնել ցանկությունը — առավել հաճախ ծարավը, բայց փոխաբերաբար ցանկացած խոր կարիք։", "Մեկ սառը բաժակ ջուր slaked նրա ծարավը երկար քայլքից հետո։", "թույլ, ազատ", "թուլացնել, հանդարտեցնել"),
    ("Ասեղաձև։", "Երկար, բարակ ու սուր ասեղի պես — սոճու ասեղի կամ սուր փոքրիկ բյուրեղի ձևը։", "Սոճիները հեշտ է ճանաչել իրենց acicular տերևներով։", "ասեղ", "փոքր"),
    ("Կենսունակությունից սպառված, թույլ, չափից նրբացված։", "Մաշված ու փափուկ — կորցրել է սկզբնական ուժն ու եռանդը չափից հարմարության կամ նրբացման պատճառով։", "Քննադատները ժամանակին համարձակ ամսագիրը կոչեցին effete — իր համարձակ վաղ տարիների ստվեր։", "դուրս", "պտղաբեր, արդեն ծնել"),
    ("Լրացուցիչ կամ փոքր կցված իր կամ իրավունք։", "Փոքր հավելում, որ կցված է ավելի մեծ բանին — պարագաներն ու հավելումները, որ պատկանում են հիմնականին։", "Վարձակալությունը ներառում էր ավտոտնակը և նրա բոլոր appurtenances։", "դեպի", "պատկանել"),
    ("Ծածկել կամ փոքրացնել մեղքը։", "Սխալը մեղմ խոսքերով հարթել, ավելի փոքր հնչեցնել, քան իրականում է։", "Նա փորձեց gloze բաց թողնված վերջնաժամկետը մշուշոտ խոսքով \"unforeseen challenges.\"", "մեկնություն, բացատրություն", "մեկնաբանել — ապա հարթել"),
    ("Վաղ փուլում, նոր սկսվող։", "Նոր է երևում — մի մեծ բանի ամենաառաջին, հազիվ տեսանելի փուլը։", "Բժիշկները բռնեցին հիվանդության incipient նշանները, նախքան տարածվելը։", "վրա, մեջ", "վերցնել (սկսել, սկիզբ դնել)"),
    ("Ստեղծագործական ներշնչանք, հատկապես աստվածային։", "Ներշնչանքի հանկարծակի հոսք, որ քեզնից մեծ է թվում — կարծես գաղափարը քո մեջ փչված լինի այլ տեղից։", "Բանաստեղծը նկարագրեց ամբողջ ստեղծագործությունը մեկ afflatus պոռթկումով գիշերվա ժամը երեքին։", "դեպի, վրա", "փչել (վրան փչել)"),
]
